`timescale 1ns/1ps
// Basys 3 top level - generated by scripts/make_experiments.py
module top_basys3 (
    input  wire        clk,                    // 100 MHz
    input  wire        btnC, btnU, btnL, btnR, // btnC = reset
    input  wire [15:0] sw,
    output wire [15:0] led,
    output wire [3:0]  an,
    output wire [6:0]  seg
);
    wire rst = btnC;
    wire en;   // one model step every 1/50 s, slow enough to watch
    step_tick #(.STEP_HZ(50)) u_tick (.clk(clk), .rst(rst), .tick(en));
    wire signed [31:0] v;  wire spike;
    qif_neuron u_n (.clk(clk), .rst(rst), .en(en), .i_in({19'd0, sw[4:0], 8'd0}), .v(v), .spike(spike));
    wire spike_led;
    pulse_stretch u_ps (.clk(clk), .rst(rst), .in(spike), .out(spike_led));
    wire signed [31:0] bar_val = v >>> 8;
    bar15 #(.FULL(30)) u_bar (.val(bar_val), .leds(led[14:0]));
    assign led[15] = spike_led;
    wire signed [31:0] num = v >>> 8;
    seg7_signed u_seg (.clk(clk), .value(num[15:0]), .an(an), .seg(seg));
endmodule
